#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.Vanilla.Contraptions;
using MVZ2Logic;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Contraptions
{
    public interface ICarrierBehaviour
    {
        void UpdateCarrier(Entity entity);
    }
    public abstract class CarrierContraptionBehaviour : EntityBehaviourDefinition, ICarrierBehaviour
    {
        public CarrierContraptionBehaviour(string nsp, string name) : base(nsp, name)
        {
            AddAura(new PassengerAura(GetPassenagerBuffID()));
            AddAura(new CarrierAura(GetCarrierBuffID()));
        }
        public void UpdateCarrier(Entity carrier)
        {
            var auraCount = carrier.GetAuraEffectCount();
            for (int i = 0; i < auraCount; i++)
            {
                var aura = carrier.GetAuraEffectAt(i);
                if (aura.Definition is CarrierAura || aura.Definition is PassengerAura)
                {
                    aura.UpdateAura();
                }
            }
        }
        protected abstract NamespaceID GetCarrierBuffID();
        protected abstract NamespaceID GetPassenagerBuffID();
        private class CarrierAura : AuraEffectDefinition
        {
            public CarrierAura(NamespaceID buffID) : base(buffID)
            {
            }
            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var sourceEnt = auraEffect.Source.GetEntity();
                if (sourceEnt != null && sourceEnt.IsOnGround && sourceEnt.HasPassenger())
                {
                    results.Add(sourceEnt);
                }
            }
        }
        private class PassengerAura : AuraEffectDefinition
        {
            public PassengerAura(NamespaceID buffID) : base(buffID)
            {
            }
            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var sourceEnt = auraEffect.Source.GetEntity();
                if (sourceEnt == null || !sourceEnt.IsOnGround)
                    return;
                using var grids = sourceEnt.GetGridsToTakeDisposeable();
                foreach (var grid in grids.Value)
                {
                    if (grid == null)
                        continue;
                    using var layersItem = grid.GetLayersDisposeable();
                    foreach (var layer in layersItem.Value)
                    {
                        using var others = grid.GetLayerEntitiesDisposeable(layer);
                        foreach (var other in others.Value)
                        {
                            if (other != null && other != sourceEnt)
                                results.Add(other);
                        }
                    }
                }
            }
        }
    }

}
